from decimal import Decimal, InvalidOperation
from typing import Any


def _decimal(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _id_key(value: Any) -> tuple[int, Any]:
    try:
        return (0, _decimal(value))
    except Exception:
        return (1, str(value))


def _same_id(left: Any, right: Any) -> bool:
    try:
        return _decimal(left) == _decimal(right)
    except Exception:
        return left == right


def sweep(
    accounts: list[dict], orders: list[dict]
) -> tuple[list[dict], list]:
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    eligible: list[tuple[Any, dict]] = [
        (index, account)
        for index, account in enumerate(accounts)
        if account.get("DEL_FLG") != "Y"
        and account.get("ACCT_TYP") == "C"
    ]
    eligible.sort(key=lambda item: _id_key(item[1].get("ACCT_ID")))

    for index, account in eligible:
        acct_id = account.get("ACCT_ID")
        exposure = Decimal(0)

        for order in orders:
            if (
                _same_id(order.get("ACCT_ID"), acct_id)
                and order.get("DEL_FLG") != "Y"
                and order.get("STAT_CD") == "I"
            ):
                exposure += _decimal(order.get("TOT_AMT"))

        credit_limit = _decimal(account.get("CRED_LIMIT"))
        updated = new_accounts[index]
        hold = updated.get("CRED_HOLD")

        if exposure > credit_limit and hold != "Y":
            updated["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if (
            exposure <= credit_limit * Decimal(8) / Decimal(10)
            and updated.get("CRED_HOLD") == "Y"
        ):
            updated["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
